version = "0.1.0"
edition = "2021"
description = "Humanity Grid Volunteer App - Donate idle compute to scientific research"
authors = ["NextEleven <sean@nexteleven.com>"]
license = "MIT"
repository = "https://github.com/seanebones-lang/Humanity-Grid"

