import { NextRequest, NextResponse } from 'next/server'
import { denyUnlessMutableApiAuthorized } from '@/lib/api-access'
import { cloneRateLimiter } from '@/lib/rate-limit'
import { config, getServiceUrl, withRetry } from '@/lib/config'
import { validateAudioFile, extractClientIP } from '@/lib/validation'
import { getCorsHeaders, handleCorsPreflight } from '@/lib/cors'

// Force dynamic rendering
export const dynamic = 'force-dynamic'

// Handle CORS preflight
export async function OPTIONS(request: NextRequest) {
  const origin = request.headers.get('origin')
  return handleCorsPreflight(origin)
}

export async function POST(request: NextRequest) {
  const denied = denyUnlessMutableApiAuthorized(request)
  if (denied) return denied

  const origin = request.headers.get('origin')
  const corsHeaders = getCorsHeaders(origin)
  try {
    // Extract and validate client IP
    const ip = extractClientIP(request)

    // Rate limiting
    const { success, limit, remaining, reset } = await cloneRateLimiter.limit(ip)

    if (!success) {
      return NextResponse.json(
        {
          error: 'Rate limit exceeded for voice cloning',
          limit,
          remaining,
          reset: new Date(reset).toISOString(),
          retryAfter: Math.ceil((reset - Date.now()) / 1000)
        },
        { 
          status: 429,
          headers: {
            'Retry-After': Math.ceil((reset - Date.now()) / 1000).toString(),
            'X-RateLimit-Limit': limit.toString(),
            'X-RateLimit-Remaining': remaining.toString(),
            'X-RateLimit-Reset': new Date(reset).toISOString(),
            ...corsHeaders,
          }
        }
      )
    }

    if (config.isRailway && !config.xttsConfigured) {
      return NextResponse.json(
        {
          error: 'Voice cloning is not available',
          hint: 'Deploy the XTTS service and set XTTS_URL to enable cloning.',
        },
        { status: 503, headers: corsHeaders }
      )
    }

    // Get form data from request
    const formData = await request.formData()

    // Validate form fields
    const name = formData.get('name')
    // Validate and sanitize name
    const nameValue = typeof name === 'string' ? name.trim() : ''
    if (!nameValue || nameValue.length === 0) {
      return NextResponse.json(
        { error: 'Name is required' }, 
        { status: 400, headers: corsHeaders }
      )
    }

    if (nameValue.length > 100) {
      return NextResponse.json(
        { error: 'Name too long (max 100 characters)' }, 
        { status: 400, headers: corsHeaders }
      )
    }

    // Sanitize name (remove special characters that could cause issues)
    const sanitizedName = nameValue.replace(/[^a-zA-Z0-9\s_-]/g, '')
    if (sanitizedName.length === 0) {
      return NextResponse.json(
        { error: 'Name contains only invalid characters' }, 
        { status: 400, headers: corsHeaders }
      )
    }

    // Validate files
    const files = formData.getAll('files') as File[]
    if (!files || files.length === 0) {
      return NextResponse.json(
        { error: 'At least one audio file is required' }, 
        { status: 400, headers: corsHeaders }
      )
    }

    if (files.length > 5) {
      return NextResponse.json(
        { error: 'Maximum 5 files allowed' }, 
        { status: 400, headers: corsHeaders }
      )
    }

    // Validate total file size (max 50MB combined)
    const totalSize = files.reduce((sum, file) => sum + file.size, 0)
    const maxTotalSize = 50 * 1024 * 1024 // 50MB
    if (totalSize > maxTotalSize) {
      return NextResponse.json(
        { error: `Total file size (${(totalSize / 1024 / 1024).toFixed(1)}MB) exceeds 50MB limit` }, 
        { status: 400, headers: corsHeaders }
      )
    }

    // Validate each file
    for (const file of files) {
      const validation = validateAudioFile(file)
      if (!validation.valid) {
        return NextResponse.json(
          { error: `Invalid file ${file.name}: ${validation.error}` },
          { status: 400, headers: corsHeaders }
        )
      }
    }

    const xttsService = config.services.xtts
    const cloneTimeoutMs = Math.min(
      240_000,
      Math.max(xttsService.timeout * 4, 120_000)
    )

    // Update formData with sanitized name
    formData.set('name', sanitizedName)

    // Forward to XTTS sidecar with retry logic
    const response = await withRetry(async () => {
      const controller = new AbortController()
      const timeout = setTimeout(() => controller.abort(), cloneTimeoutMs)

      try {
        const res = await fetch(`${xttsService.url}/clone`, {
          method: 'POST',
          body: formData,
          signal: controller.signal,
        })
        clearTimeout(timeout)
        return res
      } catch (error) {
        clearTimeout(timeout)
        throw error
      }
    }, xttsService.retries, 2000, 2)

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: 'Clone service error' })) as { detail?: string; error?: string; message?: string }
      const upstreamMessage = error.detail || error.error || error.message || 'Voice cloning failed'
      const duplicateName = response.status === 409 || /already exists|duplicate/i.test(upstreamMessage)

      return NextResponse.json(
        {
          error: duplicateName
            ? `Voice "${sanitizedName}" already exists. Please choose a different name.`
            : upstreamMessage,
        },
        { status: duplicateName ? 409 : response.status, headers: corsHeaders }
      )
    }

    const result = await response.json()

    console.log(`✓ Voice cloned: ${result.voice_id}`)

    return NextResponse.json({
      ...result,
      rateLimit: {
        limit,
        remaining: remaining - 1,
        reset: new Date(reset).toISOString(),
      },
    }, { headers: corsHeaders })
  } catch (error) {
    console.error('Voice cloning error:', error)
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to clone voice' },
      { status: 500, headers: corsHeaders }
    )
  }
}

import { NextResponse } from 'next/server'
import { config, getServiceUrl } from '@/lib/config'

export const dynamic = 'force-dynamic'

export async function GET() {
  if (config.isRailway && !config.xttsConfigured) {
    return NextResponse.json(
      { error: 'Cloned voices unavailable', reason: 'XTTS not configured' },
      { status: 503 }
    )
  }
  try {
    const xttsUrl = getServiceUrl('xtts')
    const response = await fetch(`${xttsUrl}/voices`, { cache: 'no-store' })
    if (!response.ok) {
      return NextResponse.json(
        { error: 'Cloned voices service error', status: response.status },
        { status: 503 }
      )
    }
    const data = await response.json()
    return NextResponse.json(data)
  } catch (err) {
    return NextResponse.json(
      {
        error: 'Cloned voices unavailable',
        reason: err instanceof Error ? err.message : 'Service unreachable',
      },
      { status: 503 }
    )
  }
}

/**
 * Smoke diagnostic for clone flow: health, voices list, and TTS header validation.
 * GET /api/diagnostic/clone-flow
 * Secured: require X-Diagnostic-Secret header matching env DIAGNOSTIC_SECRET, or allow localhost only.
 */

import { NextRequest, NextResponse } from 'next/server'
import { allowDiagnosticRoute } from '@/lib/api-access'
import { jsonApiError } from '@/lib/api-response'
import { config, checkServiceHealth } from '@/lib/config'
import { getCloneTelemetry } from '@/lib/monitoring'

export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
  if (!allowDiagnosticRoute(request)) {
    return jsonApiError(403, 'Forbidden', { code: 'FORBIDDEN' })
  }
  const steps: { name: string; status: 'ok' | 'degraded' | 'fail'; detail?: string }[] = []
  let overall: 'ok' | 'degraded' | 'fail' = 'ok'
  const deploymentChecklist: {
    xttsUrlConfigured: boolean
    xttsUrl: string
    gpuRecommendedForLongForm: boolean
    voicesDirPersistent?: boolean
    corsOrigins?: string[]
  } = {
    xttsUrlConfigured: config.xttsConfigured,
    xttsUrl: config.services.xtts.url,
    gpuRecommendedForLongForm: true,
  }

  try {
    // 1. XTTS service health
    const xttsHealth = await checkServiceHealth(config.services.xtts)
    if (xttsHealth.healthy) {
      steps.push({ name: 'xtts_health', status: 'ok', detail: `latency ${xttsHealth.latency}ms` })
      try {
        const xttsMetaRes = await fetch(`${config.services.xtts.url}/health`, { cache: 'no-store' })
        const xttsMeta = await xttsMetaRes.json().catch(() => ({}))
        if (typeof xttsMeta.voices_directory_persistent === 'boolean') {
          deploymentChecklist.voicesDirPersistent = xttsMeta.voices_directory_persistent
        }
        if (Array.isArray(xttsMeta.cors_origins)) {
          deploymentChecklist.corsOrigins = xttsMeta.cors_origins
        }
      } catch {
        // keep checklist best-effort only
      }
    } else {
      steps.push({ name: 'xtts_health', status: 'fail', detail: xttsHealth.error })
      overall = 'fail'
    }

    // 2. Fetch /voices (cloned + default)
    let clonedCount = 0
    try {
      const base = process.env.VERCEL_URL
        ? `https://${process.env.VERCEL_URL}`
        : process.env.NEXTAUTH_URL || 'http://localhost:3000'
      const res = await fetch(`${base}/api/voices`, { cache: 'no-store' })
      if (res.ok) {
        const data = await res.json()
        clonedCount = data.cloned_count ?? 0
        steps.push({
          name: 'voices_list',
          status: 'ok',
          detail: `default=${data.default_count ?? 0}, cloned=${clonedCount}`,
        })
      } else {
        steps.push({ name: 'voices_list', status: 'fail', detail: `HTTP ${res.status}` })
        overall = overall === 'ok' ? 'degraded' : overall
      }
    } catch (e) {
      steps.push({
        name: 'voices_list',
        status: 'fail',
        detail: e instanceof Error ? e.message : String(e),
      })
      overall = overall === 'ok' ? 'degraded' : overall
    }

    // 3. Clone telemetry
    const telemetry = getCloneTelemetry()
    steps.push({
      name: 'clone_telemetry',
      status: 'ok',
      detail: `requested=${telemetry.clone_requested} created=${telemetry.clone_created} tts_requested=${telemetry.clone_tts_requested} tts_success=${telemetry.clone_tts_success} tts_error=${telemetry.clone_tts_error}`,
    })

    return NextResponse.json({
      status: overall,
      timestamp: new Date().toISOString(),
      steps,
      deployment_checklist: deploymentChecklist,
      clone_telemetry: telemetry,
      hint:
        overall !== 'ok'
          ? 'Run clone flow: upload sample -> /api/clone-voice -> /api/voices -> POST /api/tts with voice_id=clone_* and check X-Voice-Type: cloned'
          : undefined,
    })
  } catch (error) {
    return NextResponse.json(
      {
        status: 'fail',
        error: error instanceof Error ? error.message : String(error),
        steps,
        code: 'DIAGNOSTIC_ERROR',
      },
      { status: 500 }
    )
  }
}

