  const [cloneVoicePreset, setCloneVoicePreset] = useState<'natural' | 'expressive' | 'stable'>('natural')
  const [voices, setVoices] = useState<PlaygroundVoice[]>([])
  const [loading, setLoading] = useState(false)
  const [playing, setPlaying] = useState(false)
  const [audioUrl, setAudioUrl] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [generationTime, setGenerationTime] = useState<number | null>(null)

  // Audio settings
  const [speed, setSpeed] = useState(1.0)
  const [pitch, setPitch] = useState(0)

  // Refs
  const audioRef = useRef<HTMLAudioElement>(null)

  const loadVoices = useCallback(async () => {
    try {
      // Check cache first (5 minute TTL)
      const cacheKey = 'voices_playground_cache_v2'
      const cached = sessionStorage.getItem(cacheKey)
      if (cached) {
        try {
          const { data, timestamp } = JSON.parse(cached)
          const age = Date.now() - timestamp
          if (age < 5 * 60 * 1000) { // 5 minutes
            setVoices(data.voices || [])
            if (data.voices?.length > 0 && !selectedVoice) {
              setSelectedVoice(data.voices[0].voice_id)
            }
            return
          }
        } catch {
          // Invalid cache, fetch fresh
        }
      }

      const res = await fetch('/api/voices')
      const data = await res.json()
      setVoices(data.voices || [])

      // Cache the response
      try {
        sessionStorage.setItem(cacheKey, JSON.stringify({
          data,
          timestamp: Date.now()
        }))
      } catch {
        // SessionStorage may be unavailable
      }

      if (data.voices?.length > 0) {
        setSelectedVoice(data.voices[0].voice_id)
      }
    } catch (e) {
      console.error('Failed to load voices:', e)
    }
  }, [selectedVoice])

  // Load voices on mount
  useEffect(() => {
    loadVoices()
  }, [loadVoices])

  const generateSpeech = useCallback(async () => {
    if (!text.trim()) {
      setError('Please enter some text')
      return
    }

    setLoading(true)
    setError(null)
    setAudioUrl(null)
    setGenerationTime(null)

    const startTime = Date.now()

    try {
      const voiceId = selectedVoice || 'default_english'
      const res = await fetch('/api/tts-v2', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          text: text.trim(),
          voice_id: voiceId,
          language: 'en',
          emotion: selectedEmotion,
          speed,
          pitch,
          volume: 1.0,
          reverb: 0,
          echo: 0,
          noise_reduction: false,
          special_effect: playgroundEffectToApi(selectedEffect),
          ...(voiceId.startsWith('clone_') ? { clone_preset: cloneVoicePreset } : {}),
        }),
      })

      if (!res.ok) {
        const err = await res.json().catch(() => ({}))
        throw new Error(err.error || 'Generation failed')
      }

      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      setAudioUrl(url)
      setGenerationTime(Date.now() - startTime)

      // Auto-play
      if (audioRef.current) {
        audioRef.current.src = url
        audioRef.current.play()
        setPlaying(true)
      }

    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to generate')
    } finally {
      setLoading(false)
    }
