import React from 'react'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { cn } from '@/lib/utils'

interface ResponsiveCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Card title
   */
  title?: string
  /**
   * Card description
   */
  description?: string
  /**
   * Padding variant
   * - tight: p-3 sm:p-4
   * - compact: p-4 sm:p-6
   * - default: p-6
   * - loose: p-6 sm:p-8
   */
  padding?: 'tight' | 'compact' | 'default' | 'loose'
  /**
   * Show header
   */
  showHeader?: boolean
  /**
   * Show footer
   */
  footer?: React.ReactNode
  /**
   * Responsive layout
   * - stack: Always vertical
   * - auto: Responsive (stack on mobile, side-by-side on desktop)
   */
  layout?: 'stack' | 'auto'
}

const paddingClasses = {
  tight: 'p-3 sm:p-4',
  compact: 'p-4 sm:p-6',
  default: 'p-6',
  loose: 'p-6 sm:p-8',
}

export const ResponsiveCard = React.memo(function ResponsiveCard({
  children,
  className,
  title,
  description,
  padding = 'default',
  showHeader = true,
  footer,
  layout = 'auto',
  ...props
}: ResponsiveCardProps) {
  return (
    <Card
      className={cn(
        padding !== 'default' && paddingClasses[padding],
        layout === 'auto' && 'flex flex-col sm:flex-row',
        className
      )}
      {...props}
    >
      {showHeader && (title || description) && (
        <CardHeader className={cn(
          layout === 'auto' && 'sm:w-1/3',
          padding === 'tight' && 'p-3 sm:p-4',
          padding === 'compact' && 'p-4 sm:p-6',
