/**
 * Responsive Card Grid
 * Grid of cards with responsive columns
 */
interface CardGridProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Number of columns at different breakpoints
   */
  cols?: {
    sm?: number
    md?: number
    lg?: number
    xl?: number
  }
  /**
   * Gap between cards
   */
  gap?: 'tight' | 'compact' | 'default' | 'loose'
}

const cardGridColsMap: Record<number, string> = {
  1: 'grid-cols-1',
  2: 'grid-cols-2',
  3: 'grid-cols-3',
  4: 'grid-cols-4',
  5: 'grid-cols-5',
  6: 'grid-cols-6',
  12: 'grid-cols-12',
}

const cardGridColsMapMd: Record<number, string> = {
  1: 'md:grid-cols-1',
  2: 'md:grid-cols-2',
  3: 'md:grid-cols-3',
  4: 'md:grid-cols-4',
  5: 'md:grid-cols-5',
  6: 'md:grid-cols-6',
  12: 'md:grid-cols-12',
}

const cardGridColsMapLg: Record<number, string> = {
  1: 'lg:grid-cols-1',
  2: 'lg:grid-cols-2',
  3: 'lg:grid-cols-3',
  4: 'lg:grid-cols-4',
  5: 'lg:grid-cols-5',
  6: 'lg:grid-cols-6',
  12: 'lg:grid-cols-12',
}

const cardGridColsMapXl: Record<number, string> = {
  1: 'xl:grid-cols-1',
  2: 'xl:grid-cols-2',
  3: 'xl:grid-cols-3',
  4: 'xl:grid-cols-4',
  5: 'xl:grid-cols-5',
  6: 'xl:grid-cols-6',
  12: 'xl:grid-cols-12',
}

export const CardGrid = React.memo(function CardGrid({
  children,
  className,
  cols = { sm: 1, md: 2, lg: 3 },
  gap = 'default',
  ...props
}: CardGridProps) {
  const gridCols = [
    cols.sm && cardGridColsMap[cols.sm],
    cols.md && cardGridColsMapMd[cols.md],
    cols.lg && cardGridColsMapLg[cols.lg],
    cols.xl && cardGridColsMapXl[cols.xl],
  ].filter(Boolean).join(' ')

  const gapClasses = {
    tight: 'gap-2 sm:gap-3',
    compact: 'gap-3 sm:gap-4',
    default: 'gap-4 sm:gap-6',
    loose: 'gap-6 sm:gap-8',
  }

  return (
    <div
      className={cn(
        'grid',
        gridCols || 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
        gapClasses[gap],
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
})

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline:
          "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-md px-3",
        lg: "h-11 rounded-md px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, children, ...props }, ref) => {
    const classes = cn(buttonVariants({ variant, size, className }))

    if (asChild) {
      if (React.isValidElement(children)) {
        const child = children as React.ReactElement<{ className?: string }>
        const existingClassName = child.props.className
        return React.cloneElement(child, {
          ...props,
          className: cn(classes, existingClassName),
        })
      }
      return <span className={classes}>{children}</span>
    }

    return (
      <button
        className={classes}
        ref={ref}
        {...props}
      >
        {children}
      </button>
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }

/**
 * Custom hook for managing AudioContext
 * Ensures proper cleanup and prevents memory leaks
 */
import { useRef, useEffect } from 'react'

export function useAudioContext() {
  const audioContextRef = useRef<AudioContext | null>(null)

  useEffect(() => {
    // Create AudioContext on mount
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)()
    }

    // Cleanup on unmount
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close().catch(console.error)
        audioContextRef.current = null
      }
    }
  }, [])

  return audioContextRef
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { jsonApiError } from '@/lib/api-response'

/**
 * Diagnostic/metrics routes: same trust model as `/api/diagnostic/clone-flow`.
 * - If `DIAGNOSTIC_SECRET` is set: require `x-diagnostic-secret` to match.
 * - If unset: allow only direct localhost (host prefix) and reject when `x-forwarded-for` is present
 *   (spoofing risk without a shared secret).
 */
export function allowDiagnosticRoute(request: NextRequest): boolean {
  const secret = process.env.DIAGNOSTIC_SECRET
  const provided = request.headers.get('x-diagnostic-secret')
  if (secret && provided === secret) return true
  if (!secret) {
    if (request.headers.get('x-forwarded-for')) return false
    const host = request.headers.get('host') || ''
    return host.startsWith('localhost') || host.startsWith('127.0.0.1')
  }
  return false
}

/**
 * When `API_ROUTE_SECRET` is set, POST mutation routes require either
 * `Authorization: Bearer <secret>` or `x-api-key: <secret>`.
 * When unset, behavior matches previous open API (same-origin UI works without extra headers).
 */
export function denyUnlessMutableApiAuthorized(request: NextRequest): NextResponse | null {
  const key = process.env.API_ROUTE_SECRET?.trim()
  if (!key) return null

  const auth = request.headers.get('authorization')
  const bearer =
    auth?.length && /^Bearer\s+/i.test(auth) ? auth.replace(/^Bearer\s+/i, '').trim() : ''
  const apiKey = request.headers.get('x-api-key')
  if (bearer === key || apiKey === key) return null

  return jsonApiError(401, 'Unauthorized', { code: 'UNAUTHORIZED' })
}

