// REST API Client
const TTS_API_URL = process.env.NEXT_PUBLIC_TTS_API_URL || 'http://localhost:8082'

export interface Voice {
  voice_id: string
  name: string
  description?: string
  source: 'cloned' | 'default'
  language?: string
  created_at?: string
}

export interface TTSOptions {
  text: string
  voiceId?: string
  emotion?: string
  language?: string
  speed?: number
}

export interface CloneOptions {
  name: string
  description?: string
