}

/**
 * Check TTS service health
 */
export async function checkHealth(): Promise<{
  status: string
  engine_ready: boolean
}> {
  const response = await fetch(`${TTS_API_URL}/health`)
  return response.json()
}

/**
 * List available voices
 */
export async function listVoices(): Promise<Voice[]> {
  const response = await fetch(`${TTS_API_URL}/voices`)
  const data = await response.json()
  return data.voices || []
}

/**
 * Generate speech (non-streaming)
 */
export async function synthesize(options: TTSOptions): Promise<Blob> {
  const response = await fetch(`${TTS_API_URL}/tts`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      text: options.text,
      voice_id: options.voiceId,
      emotion: options.emotion || 'neutral',
      language: options.language || 'en',
      speed: options.speed || 1.0,
    }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ detail: 'TTS failed' }))
    throw new Error(error.detail || 'TTS generation failed')
  }

  return response.blob()
}

/**
 * Clone a voice from audio files
 */
export async function cloneVoice(options: CloneOptions): Promise<{
  success: boolean
  voice_id: string
  name: string
  message: string
}> {
  const formData = new FormData()
  formData.append('name', options.name)

  if (options.description) {
    formData.append('description', options.description)
  }

  for (const file of options.files) {
    formData.append('files', file)
  }

  const response = await fetch(`${TTS_API_URL}/clone`, {
    method: 'POST',
    body: formData,
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ detail: 'Clone failed' }))
    throw new Error(error.detail || 'Voice cloning failed')
  }

  return response.json()
}

/**
 * Delete a cloned voice
 */
export async function deleteVoice(voiceId: string): Promise<void> {
  const response = await fetch(`${TTS_API_URL}/voices/${voiceId}`, {
    method: 'DELETE',
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ detail: 'Delete failed' }))
    throw new Error(error.detail || 'Failed to delete voice')
  }
}

/**
 * Play audio blob
 */
export function playAudio(blob: Blob): Promise<void> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(blob)
    const audio = new Audio(url)

    audio.onended = () => {
      URL.revokeObjectURL(url)
      resolve()
    }

    audio.onerror = (e) => {
      URL.revokeObjectURL(url)
      reject(new Error('Audio playback failed'))
    }

    audio.play().catch(reject)
  })
}

/**
 * Download audio blob as file
 */
export function downloadAudio(blob: Blob, filename?: string): void {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename || `tts-${Date.now()}.wav`
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  URL.revokeObjectURL(url)
}

/**
 * Maps UI "emotion" presets to TTS prosody (speed, pitch, levels, optional special_effect).
 * Applied on the server after validation so all clients get consistent behavior.
 */

export const ttsEmotionIds = [
  'neutral',
  'happy',
  'sad',
  'angry',
  'excited',
  'calm',
  'whisper',
  'serious',
] as const

export type TtsEmotionId = (typeof ttsEmotionIds)[number]

export type EmotionProsodyInput = {
  speed: number
  pitch: number
  volume: number
  reverb: number
  echo: number
  noise_reduction: boolean
  special_effect: string
}

export type ExpressiveIntensity = 'subtle' | 'balanced' | 'dramatic'

type ExpressiveProsodyOptions = {
  enabled?: boolean
  intensity?: ExpressiveIntensity
  isClonedVoice?: boolean
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n))
}

function isKnownEmotion(e: string): e is TtsEmotionId {
  return (ttsEmotionIds as readonly string[]).includes(e)
}

function sanitizeForExpressiveScan(text: string): string {
  return text
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/\u2026/g, '...')
    .replace(/\s+/g, ' ')
    .trim()
}

function clampPunctuationRun(n: number): number {
  return clamp(n, 0, 3)
}

/**
 * Add punctuation-aware expressive deltas to existing prosody.
 * Conservative by default (identity-safe), especially for cloned voices.
 */
export function applyExpressiveCopyProsody(
  base: EmotionProsodyInput,
  text: string,
  options: ExpressiveProsodyOptions = {}
): EmotionProsodyInput {
  if (!options.enabled) return { ...base }

  const normalized = sanitizeForExpressiveScan(text)
  if (!normalized) return { ...base }

  const intensity = options.intensity ?? 'subtle'
  const isCloned = !!options.isClonedVoice
  const styleScale = intensity === 'dramatic' ? 1.0 : intensity === 'balanced' ? 0.7 : 0.45
  const identityScale = isCloned ? 0.7 : 1.0
  const scale = styleScale * identityScale

  const exclamations = clampPunctuationRun((normalized.match(/!/g) || []).length)
  const questions = clampPunctuationRun((normalized.match(/\?/g) || []).length)
  const ellipses = clampPunctuationRun((normalized.match(/\.{3}/g) || []).length)
  const dashes = clampPunctuationRun((normalized.match(/[—–-]/g) || []).length)
  const capsWords = clampPunctuationRun((normalized.match(/\b[A-Z]{3,}\b/g) || []).length)

  const totalSignals = exclamations + questions + ellipses + dashes + capsWords
  if (totalSignals === 0) return { ...base }

  let speed = base.speed
  let pitch = base.pitch
  let volume = base.volume
  let reverb = base.reverb

  speed += (exclamations * 0.025 + capsWords * 0.02 - ellipses * 0.018 - dashes * 0.012) * scale
  pitch += (exclamations * 0.9 + questions * 0.7 + capsWords * 0.6 - ellipses * 0.4) * scale
  volume += (exclamations * 0.015 + capsWords * 0.012 - ellipses * 0.01) * scale
  reverb += (dashes + ellipses > 0 ? 0.04 : 0) * scale

  if (/[!?]\s*$/.test(normalized)) {
    if (normalized.endsWith('?')) pitch += 0.4 * scale
    if (normalized.endsWith('!')) speed += 0.02 * scale
  }

  return {
    speed: clamp(speed, 0.5, 2.0),
    pitch: clamp(pitch, -20, 20),
    volume: clamp(volume, 0, 1),
    reverb: clamp(reverb, 0, 1),
    echo: clamp(base.echo, 0, 1),
    noise_reduction: base.noise_reduction,
    special_effect: base.special_effect,
  }
}

/**
 * Layer emotion on top of user/base TTS params. Explicit `special_effect` wins unless
 * emotion is `whisper` and the user left effect as `none` (then we set whisper filter).
 */
export function applyEmotionProsody(
  base: EmotionProsodyInput,
  emotion: string | undefined
): EmotionProsodyInput {
  const raw = (emotion || 'neutral').toLowerCase()
  if (!isKnownEmotion(raw) || raw === 'neutral') {
    return { ...base }
  }

  let speed = base.speed
  let pitch = base.pitch
  let volume = base.volume
  let reverb = base.reverb
  let echo = base.echo
  let noise_reduction = base.noise_reduction
  let special_effect = base.special_effect

  switch (raw) {
    case 'happy':
      speed += 0.07
      pitch += 3
      volume = clamp(volume + 0.04, 0.15, 1)
      break
    case 'sad':
      speed -= 0.11
      pitch -= 5
      volume = clamp(volume - 0.06, 0.35, 1)
      break
    case 'angry':
      speed += 0.09
      pitch += 2
      echo = clamp(echo + 0.06, 0, 1)
      break
    case 'excited':
      speed += 0.15
      pitch += 5
      volume = clamp(volume + 0.03, 0.15, 1)
      break
    case 'calm':
      speed -= 0.07
      pitch -= 2
      reverb = clamp(reverb + 0.1, 0, 1)
      noise_reduction = true
      break
    case 'whisper':
      speed -= 0.05
      pitch -= 2
      volume = clamp(volume * 0.88, 0.35, 0.95)
      if (special_effect === 'none') special_effect = 'whisper'
      break
    case 'serious':
      speed -= 0.05
      pitch -= 3
      break
    default:
      break
  }

  return {
    speed: clamp(speed, 0.5, 2.0),
    pitch: clamp(pitch, -20, 20),
    volume: clamp(volume, 0, 1),
    reverb: clamp(reverb, 0, 1),
    echo: clamp(echo, 0, 1),
    noise_reduction,
    special_effect,
  }
}

