    data !== null &&
    'voices' in data &&
    Array.isArray((data as any).voices)
  )
}

export function isVoice(data: unknown): data is Voice {
  return (
    typeof data === 'object' &&
    data !== null &&
    'voice_id' in data &&
    'name' in data &&
    'language' in data &&
    'source' in data &&
    typeof (data as any).voice_id === 'string' &&
    typeof (data as any).name === 'string' &&
    typeof (data as any).language === 'string' &&
    typeof (data as any).source === 'string'
  )
}

/**
 * Railway worker: consumes BullMQ `voice` queue jobs created by the web app.
 * Set REDIS_URL (and DATABASE_URL if jobs persist results to Postgres).
 */
import { Worker } from "bullmq"
import { Redis } from "ioredis"
import { eq } from "drizzle-orm"
import { getDb, voiceJobs } from "@ai-voiceover/db"

const redisUrl = process.env.REDIS_URL
if (!redisUrl) {
  console.error("[workers] REDIS_URL is required")
  process.exit(1)
}

const connection = new Redis(redisUrl, { maxRetriesPerRequest: null })

const worker = new Worker(
  "voice",
  async (job) => {
    const { rowId, type } = job.data as { rowId?: string; type?: string }
    if (!rowId) {
      console.warn("[workers] job missing rowId", job.id)
      // Mark job as failed since we can't process it
      const db = getDb()
      await db
        .update(voiceJobs)
        .set({
          status: "failed",
          errorMessage: "Job missing rowId",
          updatedAt: new Date(),
        })
        .where(eq(voiceJobs.id, rowId ?? ''))
      return
    }

    const db = getDb()
    await db
      .update(voiceJobs)
      .set({
        status: "running",
        updatedAt: new Date(),
        bullmqJobId: String(job.id),
      })
      .where(eq(voiceJobs.id, rowId))

    try {
      // Stub: replace with real TTS / clone pipeline (ffmpeg, xtts, etc.)
      await job.updateProgress(15)
      await new Promise((r) => setTimeout(r, 50))
      await job.updateProgress(70)
      const result =
        type === "clone"
          ? { ok: true, outputUrl: null as string | null, note: "clone_stub" }
          : { ok: true, audioBase64: null as string | null, note: "tts_stub" }
      await job.updateProgress(100)

      await db
        .update(voiceJobs)
        .set({
          status: "succeeded",
          result: result as Record<string, unknown>,
          updatedAt: new Date(),
        })
        .where(eq(voiceJobs.id, rowId))
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      await db
        .update(voiceJobs)
        .set({
          status: "failed",
          errorMessage: message,
          updatedAt: new Date(),
        })
        .where(eq(voiceJobs.id, rowId))
      // Do NOT re-throw - let the job naturally complete
    }
  },
  { connection }
)

worker.on("failed", (job, err) => {
  console.error("[workers] job failed", job?.id, err)
})

console.log("[workers] voice queue worker started")

